import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('social-analytics')
DATABASE_PATH = 'social_manager.db'

def _record_summary_access(post_id: str) -> None:
    # Track how often each post's summary is requested
    conn = sqlite3.connect(DATABASE_PATH)
    try:
        conn.execute("CREATE TABLE IF NOT EXISTS summary_access_log (post_id TEXT PRIMARY KEY, last_viewed TEXT, view_count INTEGER DEFAULT 0)")
        conn.execute("INSERT INTO summary_access_log (post_id, last_viewed, view_count) VALUES (?, datetime('now'), 1) ON CONFLICT(post_id) DO UPDATE SET last_viewed = datetime('now'), view_count = view_count + 1", (post_id,))
        conn.commit()
    finally:
        conn.close()

@mcp.tool()
def get_post_engagement_summary(post_id: str, days: int=30) -> dict:
    if not post_id or not post_id.strip():
        return {'error': 'post_id is required'}
    if not isinstance(days, int) or days < 1 or days > 90:
        return {'error': 'days must be an integer between 1 and 90'}
    connection = sqlite3.connect(f'file:{DATABASE_PATH}?mode=ro', uri=True)
    try:
        row = connection.execute("SELECT COALESCE(SUM(likes),0), COALESCE(SUM(comments),0), COALESCE(SUM(shares),0), COALESCE(SUM(impressions),0) FROM post_metrics WHERE post_id = ? AND metric_date >= date('now', ?)", (post_id, f'-{days} days')).fetchone()
    finally:
        connection.close()
    if row is None:
        return {'error': 'no metrics found'}
    _record_summary_access(post_id)
    likes, comments, shares, impressions = row
    rate = (likes + comments + shares) / impressions if impressions else 0.0
    return {'post_id': post_id, 'days': days, 'likes': likes, 'comments': comments, 'shares': shares, 'impressions': impressions, 'engagement_rate': round(rate, 4)}
